/* Display current temperature and humidity using the built-in sensor.

We don't store any history here. To save battery we deep sleep which
means we lose everything in RAM, but we could light sleep, or could save
a history of values in Storage. */

// Image to use in the background
let image = {
  width : 800, height : 228, bpp : 2,
  buffer : atob("")
};

Badge.getTemperature().then(e => Badge.showRendering(function(g) {
  g.setColor(0).setBgColor(1).clear();
  g.drawImage(image, 0, 480-228)
  g.setFont("Vector:120").setFontAlign(0,0);
  let fahrenheit = (e.temperature * 9/5) + 32;
  g.drawString(fahrenheit.toFixed(1)+"\xB0F", 250, 130);
  g.drawString(Math.round(e.humidity)+"%", 620, 130);
  g.setFont("28").setFontAlign(0,0);
  g.drawString("Temperature", 250, 200);
  g.drawString("Humidity", 620, 200);
})).then(function() {
  // sleep 30 mins
  ESP32.deepSleep(30*60*1000000);
}).catch(e=>{
  Badge.showError(e).then(() => {
    // try again in 5 mins
    ESP32.deepSleep(10*60*1000000);
  });
});